import * as React from 'react'
import { graphql } from 'gatsby'
import { GatsbyImage, getImage } from 'gatsby-plugin-image'

import Layout from '../components/layout'
import Seo from '../components/seo'
import {useEffect,useRef} from 'react'

import Prism from 'prismjs';
import 'prismjs/components/prism-javascript';
import 'prismjs/components/prism-typescript';
import 'prismjs/components/prism-jsx';
import 'prismjs/components/prism-tsx';
import 'prismjs/components/prism-json';
import 'prismjs/components/prism-bash';
import 'prismjs/components/prism-python';
// import 'prism-themes/themes/prism-vsc-dark-plus.css';
import "../styles/code.css"
const HeroImage=({image,imageAlt})=>{
  if (image){
    return(  
      <>
        <GatsbyImage
          image={image}
          alt={imageAlt} />
        <br/>
      </>
    )
  }
  return (
    <></>
  )
}

const CodeBlock=({children,language="javascript"})=>{
  const html = Prism.highlight(
    children,
    Prism.languages[language] || Prism.languages.plain,
    language
  );

  return (
    <pre>
      <code className={`language-${language}`}
            dangerouslySetInnerHTML={{ __html: html }} />
    </pre>
  );
}
  
function PrismRenderer({ htmlContent }) {
  const containerRef = useRef(null);

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.innerHTML = htmlContent;
      Prism.highlightAllUnder(containerRef.current);
    }
  }, [htmlContent]);

  return <div ref={containerRef} />;
}

const MdLayout=({ data: { markdownRemark } })=> {
   
    const { frontmatter, html } = markdownRemark;
    const image = getImage(frontmatter.hero_image);

    useEffect(() => {
      Prism.highlightAll()
    })

    return (
      <Layout>
        <div className="md">
        <HeroImage image={image} imageAlt={frontmatter.imageAlt}></HeroImage>
        <h1>{frontmatter.title}</h1>
        <date> {frontmatter.date} </date>
        <PrismRenderer htmlContent={html}></PrismRenderer>
        <div dangerouslySetInnerHTML={{ __html: html }} />
      </div>
      </Layout>
    );   
}

export const query = graphql`
  query($id: String) {
    markdownRemark(id: { eq: $id }) {
      frontmatter {
        title
        date(formatString: "MMMM DD, YYYY")
        hero_image {
          childImageSharp {
            gatsbyImageData
          }
        }
        hero_image_alt
      }
      html
   }
  }
`

export const Head = ({ data }) => <Seo title={data.markdownRemark.frontmatter.title} />

export default MdLayout